struct TriangleHit
{
    float t;

    // Barycentrics corresponding to A, B, C.
    float w;
    float u;
    float v;
};

std::optional<TriangleHit>
IntersectTriangle(
    const Ray& ray,
    Vec3 A,
    Vec3 B,
    Vec3 C)
{
    constexpr float epsilon = 1.0e-8f;

    const Vec3 E1 = B - A;
    const Vec3 E2 = C - A;

    // pvec is perpendicular to both ray direction and E2.
    const Vec3 pvec =
        Cross(ray.direction, E2);

    const float determinant =
        Dot(E1, pvec);

    // Near-zero determinant means:
    // - triangle is degenerate, or
    // - ray is parallel to triangle plane.
    if (std::abs(determinant) < epsilon)
        return std::nullopt;

    const float inverseDet =
        1.0f / determinant;

    const Vec3 tvec =
        ray.origin - A;

    const float u =
        Dot(tvec, pvec) *
        inverseDet;

    if (u < 0.0f || u > 1.0f)
        return std::nullopt;

    const Vec3 qvec =
        Cross(tvec, E1);

    const float v =
        Dot(ray.direction, qvec) *
        inverseDet;

    if (v < 0.0f || u + v > 1.0f)
        return std::nullopt;

    const float t =
        Dot(E2, qvec) *
        inverseDet;

    if (t < ray.tMin ||
        t > ray.tMax)
    {
        return std::nullopt;
    }

    return TriangleHit
    {
        .t = t,
        .w = 1.0f - u - v,
        .u = u,
        .v = v
    };
}

